		query, args := sql.BuildHardDelete(c.dialect, c.table, sql.HardDeleteOptions{
			Conditions: []sql.Condition{
				sql.Where(c.dialect.QuoteIdentifier("id")).In(toAnySlice(ids)...),
			},
		})

		_, err := conn.Exec(ctx, query, args...)
